{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "Despite these scientific advancements on sustainability determinants, there is a lack of guidance on how to select the most appropriate theoretical approach to evaluate the sustainability of EBIs in healthcare. ... Most evaluations in this integrative review applied determinant theoretical approaches, that focus on predictors of sustainability (organizational, contextual, human, and processes), but they did not link these determinants to, and, or measure patient or system level outcomes, such as sustained patient or staff benefit [6]. For those studies that did measure any of the nine sustainability outcomes, there was a lack of correlation between the outcome (e.g., maintenance of policy) and long-term impact on patient or system outcomes.",
      "reason": "The text describes the current state of knowledge regarding sustainability evaluation (e.g., focus on determinants rather than outcomes) and identifies uncertainties/gaps (lack of guidance on selecting theoretical approaches, lack of correlation between outcomes and long-term impact)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "As evaluation is necessary to determine effectiveness, this review aimed to improve our understanding of how the sustainability of EBIs in healthcare is evaluated. A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. ... Therefore, we provide evidence on theoretical approaches used for evaluation, including how and when they have been used, and offer new guidance and synthesis on the combination of approaches for evaluating sustainability of EBIs.",
      "reason": "The authors explain the importance of the review by highlighting the need to understand how sustainability is evaluated to determine effectiveness and to provide guidance on selecting theoretical approaches, distinguishing it from previous syntheses."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. ... Our synthesis indicated that there is a breadth of theoretical approaches and constructs that were considered for the evaluation of the sustainability of EBIs in healthcare that were consistent with other recent synthesis work [6-10].",
      "reason": "The authors acknowledge the existence of recent syntheses (e.g., Lennox et al. [6]) and explain how their review differs (focus on evaluation) and how it relates to existing work."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is an integrative review of approaches to evaluate sustainability, not a review of the effects of a specific intervention; therefore, a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review is not evaluating a specific complex intervention or delivery context that requires a logic model to show hypothesized relationships between components and outcomes; it is a methodological review of evaluation approaches."
    }
  ],
  "confidence": 100
}

{
